        for z in zero_positions:
            if f > z:
                moves = z + (length - f - 1)
                min_moves = min(min_moves, moves)

    # Try to form '50'
    for f in five_positions:
        for z in zero_positions:
            if f < z:
                moves = f + (length - z - 1)
                min_moves = min(min_moves, moves)

